create or replace function public.create_employee(p_name text,p_phone text default null,p_department text default null,p_job text default null,p_shift text default null,p_employment_date date default null,p_wage_type text default 'monthly',p_base_salary numeric default 0,p_notes text default null) returns public.employees language plpgsql security definer set search_path=public as $$declare e public.employees;d uuid;j uuid;sh uuid;begin if auth.uid() is null or not public.current_user_has_permission('employees.create') then raise exception 'غير مصرح بإضافة عامل';end if;if nullif(btrim(p_name),'') is null then raise exception 'اسم العامل مطلوب';end if;if p_department is not null and nullif(btrim(p_department),'') is not null then insert into public.departments(name) values(btrim(p_department)) on conflict(name) do update set name=excluded.name returning id into d;end if;if p_job is not null and nullif(btrim(p_job),'') is not null then insert into public.job_titles(name) values(btrim(p_job)) on conflict(name) do update set name=excluded.name returning id into j;end if;if p_shift is not null and nullif(btrim(p_shift),'') is not null then insert into public.shifts(name) values(btrim(p_shift)) on conflict(name) do update set name=excluded.name returning id into sh;end if;insert into public.employees(full_name,phone,department_id,job_title_id,shift_id,employment_date,wage_type,base_salary,notes,created_by) values(btrim(p_name),p_phone,d,j,sh,p_employment_date,coalesce(nullif(p_wage_type,''),'monthly'),greatest(p_base_salary,0),p_notes,auth.uid()) returning * into e;return e;end;$$;
create or replace function public.toggle_employee_attendance(p_employee_id uuid) returns public.attendance_records language plpgsql security definer set search_path=public as $$declare a public.attendance_records;begin if auth.uid() is null or not public.current_user_has_permission('attendance.create') then raise exception 'غير مصرح بتسجيل الحضور';end if;select * into a from public.attendance_records where employee_id=p_employee_id and work_date=current_date for update;if a.id is null then insert into public.attendance_records(employee_id,check_in_at,status,created_by) values(p_employee_id,now(),'present',auth.uid()) returning * into a;elsif a.check_out_at is null then update public.attendance_records set check_out_at=now() where id=a.id returning * into a;else raise exception 'تم تسجيل الحضور والانصراف لهذا العامل اليوم';end if;return a;end;$$;
create or replace function public.create_employee_advance(p_employee_id uuid,p_amount numeric,p_reason text,p_payment_method text,p_cash_register_id uuid default null,p_bank_id uuid default null) returns public.employee_advances language plpgsql security definer set search_path=public as $$declare a public.employee_advances;begin if auth.uid() is null or not public.current_user_has_permission('payroll.manage') then raise exception 'غير مصرح بتسجيل سلفة';end if;if p_employee_id is null or p_amount<=0 then raise exception 'اختر العامل وأدخل مبلغًا صحيحًا';end if;if p_payment_method='cash' and p_cash_register_id is null then raise exception 'اختر الخزنة';end if;if p_payment_method='bank' and p_bank_id is null then raise exception 'اختر البنك';end if;insert into public.employee_advances(employee_id,amount,reason,remaining_amount,payment_method,cash_register_id,bank_id,created_by) values(p_employee_id,p_amount,p_reason,p_amount,p_payment_method,p_cash_register_id,p_bank_id,auth.uid()) returning * into a;if p_payment_method='cash' then insert into public.cash_transactions(cash_register_id,direction,transaction_type,amount,related_type,related_id,created_by,notes) values(p_cash_register_id,'out','employee_advance',p_amount,'employee_advance',a.id,auth.uid(),p_reason);else insert into public.bank_transactions(bank_id,direction,transaction_type,amount,related_type,related_id,created_by,notes) values(p_bank_id,'out','employee_advance',p_amount,'employee_advance',a.id,auth.uid(),p_reason);end if;return a;end;$$;
create or replace function public.grant_employee_incentive(p_employee_id uuid,p_amount numeric,p_reason text,p_period_start date default null,p_period_end date default null) returns public.employee_incentives language plpgsql security definer set search_path=public as $$declare i public.employee_incentives;begin if auth.uid() is null or not public.current_user_has_permission('payroll.manage') then raise exception 'غير مصرح بمنح حافز';end if;if p_employee_id is null or p_amount<=0 or nullif(btrim(p_reason),'') is null then raise exception 'اختر العامل وأدخل القيمة والسبب';end if;insert into public.employee_incentives(employee_id,amount,reason,period_start,period_end,created_by) values(p_employee_id,p_amount,btrim(p_reason),p_period_start,p_period_end,auth.uid()) returning * into i;return i;end;$$;
create or replace function public.prepare_payroll_period(p_name text,p_from date,p_to date) returns public.payroll_periods language plpgsql security definer set search_path=public as $$declare pp public.payroll_periods;e record;inc numeric;adv numeric;begin if auth.uid() is null or not public.current_user_has_permission('payroll.manage') then raise exception 'غير مصرح بإعداد المرتبات';end if;if p_from is null or p_to is null or p_to<p_from then raise exception 'الفترة غير صحيحة';end if;insert into public.payroll_periods(period_name,from_date,to_date,created_by) values(p_name,p_from,p_to,auth.uid()) returning * into pp;for e in select * from public.employees where status='active' loop select coalesce(sum(amount),0) into inc from public.employee_incentives where employee_id=e.id and status='approved' and (period_start is null or period_start<=p_to) and (period_end is null or period_end>=p_from);select coalesce(sum(remaining_amount),0) into adv from public.employee_advances where employee_id=e.id and remaining_amount>0;insert into public.payroll_records(period_id,employee_id,base_amount,incentives,advance_deduction) values(pp.id,e.id,e.base_salary,inc,least(adv,e.base_salary+inc));end loop;return pp;end;$$;
create or replace function public.approve_payroll_period(p_period_id uuid) returns public.payroll_periods language plpgsql security definer set search_path=public as $$declare pp public.payroll_periods;r record;ded numeric;begin if auth.uid() is null or not public.current_user_has_permission('payroll.manage') then raise exception 'غير مصرح باعتماد المرتبات';end if;select * into pp from public.payroll_periods where id=p_period_id for update;if pp.id is null then raise exception 'الفترة غير موجودة';end if;if pp.status<>'draft' then raise exception 'الفترة اعتمدت أو ألغيت سابقًا';end if;update public.payroll_periods set status='approved',approved_by=auth.uid(),approved_at=now() where id=pp.id returning * into pp;for r in select * from public.payroll_records where period_id=pp.id loop ded:=r.advance_deduction;update public.employee_advances set remaining_amount=greatest(remaining_amount-ded,0) where employee_id=r.employee_id and remaining_amount>0;end loop;return pp;end;$$;
grant execute on function public.create_employee(text,text,text,text,text,date,text,numeric,text) to authenticated;grant execute on function public.toggle_employee_attendance(uuid) to authenticated;grant execute on function public.create_employee_advance(uuid,numeric,text,text,uuid,uuid) to authenticated;grant execute on function public.grant_employee_incentive(uuid,numeric,text,date,date) to authenticated;grant execute on function public.prepare_payroll_period(text,date,date) to authenticated;grant execute on function public.approve_payroll_period(uuid) to authenticated;
